from textsx import X
P="AR-Y8-NN-"
X(P+"T1-L01","قصة آدم","كان آدم طالبًا جديدًا في المدرسة.|بعض الطلاب سخروا من لغته ولهجته.|ثمّ بدأ التنمّر الإلكتروني برسائل مؤذية.|شجّعته صديقته على أن يبلّغ المعلّم.|تدخّلت المدرسة، وتعلّم الجميع أن يحترموا الآخرين.","كان آدم طالبًا قديمًا في المدرسة-|بلّغ آدم المعلّم+|تعلّم الطلاب الاحترام+","ماذا فعل بعض الطلاب بآدم؟ سخروا من لغته ولهجته.|من شجّع آدم على التبليغ؟ صديقته.")
X(P+"T1-L02","عام التسامح","أعلنت الإمارات عام ٢٠١٩ عامًا للتسامح.|يعيش في الإمارات أكثر من مئتي جنسية.|يتعايش الناس من ثقافات وديانات مختلفة في احترام.|وأُطلقت مبادرات كثيرة لنشر قيم التعايش.|التسامح يجعل المجتمع قويًّا وآمنًا.","عام التسامح كان ٢٠١٩+|يعيش في الإمارات عشر جنسيات فقط-|التسامح يجعل المجتمع قويًّا+","كم جنسية تعيش في الإمارات؟ أكثر من مئتي جنسية.|ماذا يفعل التسامح بالمجتمع؟ يجعله قويًّا وآمنًا.")
X(P+"T1-L03","صديقي من بلد آخر","جاء كينجي من اليابان إلى صفّي.|لغته مختلفة وعاداته مختلفة.|في البداية شعر بالغربة ولم يتكلّم كثيرًا.|عرّفته على زملائي، وعلّمته كلمات عربية.|اليوم نحن صديقان، وأتعرّف منه على ثقافة اليابان.","جاء كينجي من الصين-|شعر كينجي بالغربة في البداية+|أصبح الكاتب وكينجي صديقين+","من أين جاء كينجي؟ من اليابان.|ماذا علّمه الكاتب؟ كلمات عربية.")
X(P+"T1-L04","رحلة جبل السلامة","ذهب صفّنا في رحلة إلى الجبل.|قبل الصعود قرأ المرشد تعليمات السلامة.|تعثّر زميلي وجُرحت يده.|قدّم المعلّم الإسعافات الأولية بسرعة.|تعلّمنا أنّ اتّباع التعليمات يحمينا من الخطر.","قرأ المرشد التعليمات بعد الصعود-|قدّم المعلّم الإسعافات الأولية+|التعليمات تحمينا من الخطر+","ماذا حدث للزميل؟ تعثّر وجُرحت يده.|ماذا تعلّم الطلاب؟ أنّ اتّباع التعليمات يحمينا.")
X(P+"T1-L05","نتحاور ونختلف","في الصف أجرينا حوارًا عن الألعاب الإلكترونية.|كان لكلّ طالب رأي مختلف.|أصغينا إلى الآراء كلّها دون تعصّب.|تقبّلتُ رأي زميلي وإن كنت لا أوافقه.|الشخص المنفتح يحترم التنوّع ويتعلّم من غيره.","كان الحوار عن الرياضة-|استمع الطلاب للآراء دون تعصّب+|المنفتح يتعلّم من غيره+","ما موضوع الحوار؟ الألعاب الإلكترونية.|ماذا يفعل الشخص المنفتح؟ يحترم التنوّع ويتعلّم من غيره.")
X(P+"T1-L06","أشياء تسعدني","يسعدني أن أقضي الوقت مع أسرتي.|وأشعر بالسعادة عندما أساعد صديقًا.|أكتب كل مساء ثلاثة أشياء أنا ممتنّ لها.|التفكير الإيجابي يجعلني أبتسم أكثر.|السعادة لا تحتاج إلى أشياء غالية.","الكاتب يكتب أشياء يمتنّ لها كل صباح-|مساعدة الصديق تسعد الكاتب+|السعادة تحتاج أشياء غالية-","ماذا يكتب الكاتب كل مساء؟ ثلاثة أشياء يمتنّ لها.|ماذا يفعل التفكير الإيجابي؟ يجعله يبتسم أكثر.")
X(P+"T1-L07","فوضى في الممر","في الاستراحة تحوّل الممر إلى فوضى.|ركض بعض الطلاب وصرخوا ودفعوا زملاءهم.|سقط طالب صغير وبكى.|ذكّر المدير الجميع بنظام المدرسة والعقوبات.|من يومها نمشي بهدوء ونحترم النظام.","كان الممر هادئًا-|سقط طالب صغير+|يمشي الطلاب الآن بهدوء+","ماذا حدث للطالب الصغير؟ سقط وبكى.|ماذا ذكّر المدير الطلاب؟ بنظام المدرسة والعقوبات.")
X(P+"T1-L08","لن أستسلم","رسبت مريم في اختبار الرياضيات الأول.|لم تتشاءم، وقالت: «سأحاول من جديد».|درست كل يوم وطلبت المساعدة من معلّمتها.|في الاختبار الثاني نجحت بدرجة عالية.|التفاؤل والأمل يساعداننا على تجاوز الصعوبات.","تشاءمت مريم بعد الاختبار-|طلبت مريم المساعدة من معلّمتها+|نجحت مريم في الاختبار الثاني+","ماذا قالت مريم بعد الرسوب؟ سأحاول من جديد.|ماذا يساعدنا على تجاوز الصعوبات؟ التفاؤل والأمل.")
X(P+"T1-L09","بنك الطعام","في العالم ملايين الناس يعانون من الجوع.|وفي المقابل يُهدر طعام كثير في المطاعم والبيوت.|يجمع بنك الطعام في الإمارات الطعام الزائد.|ثمّ يوصله إلى المحتاجين بأمان.|نستطيع أن نتبرّع ونقلّل الهدر في بيوتنا.","لا يعاني أحد من الجوع-|بنك الطعام يجمع الطعام الزائد+|نستطيع تقليل الهدر+","ماذا يفعل بنك الطعام؟ يجمع الطعام الزائد ويوصله إلى المحتاجين.|كيف نساعد؟ نتبرّع ونقلّل الهدر.")
X(P+"T1-L10","عندما أغضب","غضب حمد عندما خسر فريقه المباراة.|صرخ على صديقه، ثمّ شعر بالندم.|علّمه أبوه طريقة جديدة: «تنفّس وعُدّ إلى عشرة».|في المرة التالية هدأ قبل أن يتكلّم.|واعتذر لصديقه، فعادت صداقتهما أقوى.","غضب حمد لأنّ فريقه فاز-|علّمه أبوه أن يعدّ إلى عشرة+|اعتذر حمد لصديقه+","لماذا غضب حمد؟ لأنّ فريقه خسر المباراة.|ما الطريقة الجديدة؟ أن يتنفّس ويعدّ إلى عشرة.")
X(P+"T2-L01","مزرعة جدّي","لجدّي مزرعة صغيرة في العين.|يزرع النخيل والخضار والفواكه.|يضع البذور في الربيع ويريّها كل صباح.|يستخدم سمادًا طبيعيًّا ليكون المحصول صحّيًّا.|في الصيف نجمع المحصول معًا ونبيع جزءًا منه.","مزرعة الجدّ في دبي-|يريّ الجدّ الزرع كل صباح+|يستخدم سمادًا طبيعيًّا+","أين مزرعة الجدّ؟ في العين.|متى يجمعون المحصول؟ في الصيف.")
X(P+"T2-L02","رئة الأرض","الغابات رئة الأرض، فهي تعطينا الأكسجين.|تعيش فيها كائنات كثيرة.|لكنّ قطع الأشجار والحرائق تهدّدها.|في الإمارات نحمي غابات المانغروف على الشاطئ.|زراعة شجرة واحدة تساعد كوكبنا.","الغابات تعطينا الأكسجين+|غابات المانغروف في الصحراء-|قطع الأشجار يهدّد الغابات+","ماذا تعطينا الغابات؟ الأكسجين.|أين غابات المانغروف؟ على الشاطئ.")
X(P+"T2-L03","أقلّل نفاياتي","تنتج كل أسرة نفايات كثيرة كل يوم.|أكثرها بلاستيك يبقى في الأرض سنوات طويلة.|في بيتنا نفرز الورق والبلاستيك والزجاج.|ثمّ نرسلها إلى إعادة التدوير.|وأحمل كيسًا قماشيًّا عند التسوّق لأقلّل البلاستيك.","البلاستيك يختفي بسرعة-|الأسرة تفرز النفايات+|الكاتب يحمل كيسًا قماشيًّا+","ماذا تفرز الأسرة؟ الورق والبلاستيك والزجاج.|لماذا يحمل الكاتب كيسًا قماشيًّا؟ ليقلّل البلاستيك.")
X(P+"T2-L04","طاقة اليوم والغد","النفط مصدر مهمّ للطاقة، لكنه سينفد يومًا.|الطاقة الشمسية وطاقة الرياح متجدّدة.|في الإمارات مجمّعات كبيرة للطاقة الشمسية.|وفيها محطة براكة للطاقة النووية السلمية.|الطاقة النظيفة تحمي البيئة للأجيال القادمة.","النفط طاقة متجدّدة-|في الإمارات محطة طاقة نووية سلمية+|الطاقة النظيفة تحمي البيئة+","اذكر طاقة متجدّدة. الطاقة الشمسية أو طاقة الرياح.|ما اسم محطة الطاقة النووية؟ براكة.")
X(P+"T2-L05","روبوت المدرسة","في مدرستنا روبوت صغير يستقبل الزوّار.|برمجناه في نادي العلوم.|فيه مستشعر يعرف إن اقترب شخص منه.|الروبوتات تقوم بمهامّ خطرة بدل الإنسان.|والذكاء الاصطناعي يجعلها أذكى كل يوم.","برمج الطلاب الروبوت في نادي العلوم+|ليس في الروبوت مستشعر-|الروبوتات تقوم بمهامّ خطرة+","ماذا يفعل روبوت المدرسة؟ يستقبل الزوّار.|ماذا يفعل المستشعر؟ يعرف إن اقترب شخص منه.")
X(P+"T2-L06","مسبار الأمل","أطلقت الإمارات مسبار الأمل إلى المرّيخ عام ٢٠٢٠.|وصل المسبار إلى مدار المرّيخ عام ٢٠٢١.|يدرس المسبار الغلاف الجوّي للكوكب الأحمر.|ويرسل بيانات مهمّة للعلماء في العالم.|أصبحت الإمارات أول دولة عربية تصل إلى المرّيخ.","أُطلق المسبار عام ٢٠٢٠+|المسبار يدرس القمر-|الإمارات أول دولة عربية تصل إلى المرّيخ+","متى وصل المسبار إلى المرّيخ؟ عام ٢٠٢١.|ماذا يدرس المسبار؟ الغلاف الجوّي للمرّيخ.")
X(P+"T3-L01","قدوتنا","القدوة شخص نتعلّم من أخلاقه وأفعاله.|كان الشيخ زايد قدوة في العطاء والحكمة.|ساعد الناس داخل الإمارات وخارجها.|القدوة الملهم لا يحتاج إلى منصب كبير.|قد يكون معلّمًا أو أبًا أو صديقًا يخدم وطنه.","القدوة يحتاج دائمًا إلى منصب كبير-|كان الشيخ زايد قدوة في العطاء+|قد يكون القدوة معلّمًا+","ما القدوة؟ شخص نتعلّم من أخلاقه وأفعاله.|بماذا كان الشيخ زايد قدوة؟ في العطاء والحكمة.")
X(P+"T3-L02","نحن الإمارات","قام اتحاد الإمارات عام ١٩٧١.|المؤسّس هو الشيخ زايد بن سلطان آل نهيان رحمه الله.|اتّحدت الإمارات السبع لترتقي معًا.|الولاء للوطن يعني أن نحبّه ونعمل لأجله.|ونعتزّ بعلمنا ونحتفل باليوم الوطني كل عام.","قام الاتحاد عام ١٩٧١+|اتّحدت خمس إمارات-|الولاء أن نعمل لأجل الوطن+","من مؤسّس الاتحاد؟ الشيخ زايد بن سلطان آل نهيان.|ماذا يعني الولاء؟ أن نحبّ الوطن ونعمل لأجله.")
X(P+"T3-L03","يد واحدة","في الأزمات يظهر التكاتف بين الناس.|يتبرّع بعضهم بالمال، ويتطوّع آخرون بالوقت.|ساند المتطوّعون الأسر في أيام الأمطار الغزيرة.|التطوّع ليس عملًا إضافيًّا، بل غاية نبيلة.|به يتحقّق الأمن والسعادة للمجتمع.","التكاتف يظهر في الأزمات+|التطوّع عمل غير مهمّ-|ساند المتطوّعون الأسر في الأمطار+","كيف يساعد الناس في الأزمات؟ بالتبرّع بالمال والتطوّع بالوقت.|ماذا يتحقّق بالتطوّع؟ الأمن والسعادة للمجتمع.")
X(P+"T3-L04","إعلان ذكي","نرى الإعلانات في كل مكان: في الشارع والهاتف.|يستخدم التسويق صورًا جميلة وكلمات جذّابة.|بعض الإعلانات تعرض خصومات كبيرة.|علينا أن نسأل: هل المنتج ملائم لي فعلًا؟|المستهلك الذكي لا يشتري كل ما يراه.","الإعلانات في الشارع فقط-|بعض الإعلانات تعرض خصومات+|المستهلك الذكي يشتري كل شيء-","أين نرى الإعلانات؟ في الشارع والهاتف.|ماذا يسأل المستهلك الذكي؟ هل المنتج ملائم لي فعلًا؟")
X(P+"T3-L05","مائدة الكرم","الضيافة من أجمل عادات أهل الإمارات.|يقدّمون القهوة والتمر للضيف أولًا.|ومن الأطباق الشعبية الهريس والمجبوس.|للطعام إتيكيت: نأكل باليمين ونشكر المضيف.|الكرم عادة توارثها الأبناء عن الآباء.","يقدّمون العصير للضيف أولًا-|الهريس طبق شعبي+|نأكل باليمين+","ماذا يقدّمون للضيف أولًا؟ القهوة والتمر.|اذكر طبقًا شعبيًّا. الهريس أو المجبوس.")
X(P+"T3-L06","زيّنا الشعبي","للإمارات زيّ شعبي موروث.|يلبس الرجل الكندورة والغترة.|وتلبس المرأة العباءة والملابس المطرّزة.|في المهرجانات يظهر جمال اللباس الشعبي.|ويضيف المصمّمون اليوم لمسات حديثة على الإطلالة التقليدية.","يلبس الرجل الكندورة+|اللباس الشعبي لا يظهر في المهرجانات-|يضيف المصمّمون لمسات حديثة+","ماذا يلبس الرجل؟ الكندورة والغترة.|أين يظهر جمال اللباس الشعبي؟ في المهرجانات.")
